const search = document.querySelector('#search');
const grid = document.querySelector('#grid');
const count = document.querySelector('#count');
const picked = document.querySelector('#picked');

const courses = [
  { title: '자바스크립트 입문', level: '입문', hours: 12 },
  { title: '리액트 시작하기', level: '보통', hours: 20 },
  { title: 'CSS 레이아웃 마스터', level: '보통', hours: 8 },
  { title: '자바스크립트 심화', level: '심화', hours: 24 },
  { title: '접근성 기초', level: '입문', hours: 6 },
];

const cardOf = (course) => `
  <article class="course" data-title="${course.title}">
    <h3 class="course__title">${course.title}</h3>
    <p class="course__meta">${course.level} · ${course.hours}시간</p>
    <button class="course__pick" type="button">담기</button>
  </article>
`;

const state = { keyword: '', order: 'asc' };

const visibleOf = () => null; // ← 여기를 채우세요

const render = () => {
  const visible = visibleOf();

  count.textContent = `코스 ${visible.length}개`;

  if (visible.length === 0) {
    grid.innerHTML = '<p class="empty">조건에 맞는 코스가 없습니다.</p>';
    return;
  }

  grid.innerHTML = visible.map(cardOf).join('');
};

render();

search.addEventListener('input', () => {
  state.keyword = search.value;
  render();
});

document.querySelector('#asc').addEventListener('click', () => {
  state.order = 'asc';
  render();
});

document.querySelector('#desc').addEventListener('click', () => {
  state.order = 'desc';
  render();
});

grid.addEventListener('click', (event) => {
  const button = event.target.closest('.course__pick');
  if (button === null) return;

  picked.textContent = `담은 코스: ${button.closest('.course').dataset.title}`;
});

